mapper.select:
SELECT p.post_id, p.board_type_code, p.title, p.notice_gubun_code, COALESCE(p.contents_html, p.contents, '') AS contents, p.contents_html, p.contents_json, p.contents_text, p.writer_id, p.writer_name, p.last_modified_by, p.last_modified_by_name, p.view_count, p.is_notice, p.is_deleted, p.created_at, p.updated_at, COALESCE(( SELECT COUNT(*) FROM tb_board_file bf WHERE bf.post_id = p.post_id AND bf.deleted_yn = 'N' ), 0) AS attachment_count FROM tb_board_post p WHERE p.board_type_code = #{boardTypeCode} AND p.is_deleted = 'N'
AND ( p.title ILIKE '%' || #{keyword} || '%' OR p.writer_name ILIKE '%' || #{keyword} || '%' OR p.contents_text ILIKE '%' || #{keyword} || '%' )
AND p.notice_gubun_code = #{noticeGubunCode}
ORDER BY p.is_notice DESC, p.created_at DESC LIMIT #{size} OFFSET #{offset}
